def eval_expression(expr: str) -> float:
    def tokenize(expression):
        tokens = []
        i = 0
        n = len(expression)
        while i < n:
            char = expression[i]

            if char.isspace():
                i += 1
                continue

            # Handle numbers (including decimals and negative numbers)
            if char.isdigit() or char == '.':
                num_str = ''
                while i < n and (expression[i].isdigit() or expression[i] == '.'):
                    num_str += expression[i]
                    i += 1
                tokens.append(float(num_str) if '.' in num_str else int(num_str))
                continue

            # Handle negative numbers or unary minus
            if char == '-':
                # It's a unary minus if it's the first character or follows an operator or open paren
                if i == 0 or expression[i-1] in "(+-*/":
                    i += 1
                    # Skip spaces after the negative sign
                    while i < n and expression[i].isspace():
                        i += 1
                    num_str = '-'
                    while i < n and (expression[i].isdigit() or expression[i] == '.'):
                        num_str += expression[i]
                        i += 1
                    if len(num_str) > 1: # Successfully parsed a negative number
                        tokens.append(float(num_str) if '.' in num_str else int(num_str))
                        continue
                    else:
                        # Fallback if '-' is just treated as an operator with a 0 implied, 
                        # but standard unary minus parsing:
                        tokens.append(-1)
                        tokens.append('*')
                        continue

            if char in "+-*/()":
                tokens.append(char)
                i += 1
                continue

            raise ValueError(f"Invalid character in expression: {char}")

        return tokens

    def to_rpn(tokens):
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        output = []
        operator_stack = []

        for token in tokens:
            if isinstance(token, (int, float)):
                output.append(token)
            elif token in precedence:
                while (operator_stack and operator_stack[-1] in precedence and
                       precedence[operator_stack[-1]] >= precedence[token]):
                    output.append(operator_stack.pop())
                operator_stack.append(token)
            elif token == '(':
                operator_stack.append(token)
            elif token == ')':
                while operator_stack and operator_stack[-1] != '(':
                    output.append(operator_stack.pop())
                if not operator_stack:
                    raise ValueError("Mismatched parentheses")
                operator_stack.pop() # Remove '('

        while operator_stack:
            op = operator_stack.pop()
            if op == '(':
                raise ValueError("Mismatched parentheses")
            output.append(op)

        return output

    def evaluate_rpn(rpn):
        stack = []
        for token in rpn:
            if isinstance(token, (int, float)):
                stack.append(token)
            else:
                if len(stack) < 2:
                    raise ValueError("Invalid expression")
                b = stack.pop()
                a = stack.pop()

                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    if b == 0:
                        raise ZeroDivisionError("Division by zero")
                    stack.append(a / b)

        if len(stack) != 1:
            raise ValueError("Invalid expression")

        result = stack[0]
        # Return as int if it's a whole number, matching standard expectations
        if isinstance(result, float) and result.is_integer():
            return int(result)
        return result

    tokens = tokenize(expr)
    rpn = to_rpn(tokens)
    return evaluate_rpn(rpn)

# --- Examples ---
